namespace Api.Web.FinanceIA.Models.Financia;

/// <summary>
/// EF Core entity that maps to [dbo].[SessionLogs].
/// Append-only session event log — records are never updated or deleted.
/// </summary>
public sealed class SessionLog
{
    /// <summary>Primary key, auto-generated by the database.</summary>
    public long SessionLogId { get; set; }

    /// <summary>Tenant that owns this session entry.</summary>
    public Guid TenantId { get; set; }

    /// <summary>User associated with the session event, or null for pre-auth failures.</summary>
    public Guid? UserId { get; set; }

    /// <summary>Email address used during the authentication attempt.</summary>
    public string? Email { get; set; }

    /// <summary>
    /// Type of session event.
    /// Example values: Login.Success, Login.Failed, Logout, TokenRefresh.
    /// </summary>
    public string EventType { get; set; } = string.Empty;

    /// <summary>IP address of the client.</summary>
    public string? IpAddress { get; set; }

    /// <summary>User-Agent header from the request.</summary>
    public string? UserAgent { get; set; }

    /// <summary>Reason for failure when the event represents an unsuccessful attempt.</summary>
    public string? FailureReason { get; set; }

    /// <summary>UTC timestamp when the session event occurred.</summary>
    public DateTime Timestamp { get; set; }
}
